INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-12', 'ishoot-client-onboarding', 'What Happens in Your First 14 Days With ishoot', 'خارطة الأيام الـ14 الأولى مع فريق آي شوت', 'Key operational benchmarks, real metrics, and 2026 guidance from ishoot in Manama.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من آي شوت في Manama.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Premier cinematic media production house in the Kingdom of Bahrain, crafting narrative-driven brand films, commercials, and aerial cinematography. Focusing on Executive Video Podcast Production, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"دار إنتاج سينمائي رائدة في مملكة البحرين، متخصصة في صناعة الأفلام الإعلانية الوثائقية والتصوير الجوي السينمائي. من خلال خدمة إنتاج البودكاست المرئي التنفيذي نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Premier cinematic media production house in the Kingdom of Bahrain, crafting narrative-driven brand films, commercials, and aerial cinematography.</p><p>Focusing on <strong>Executive Video Podcast Production</strong>, our Manama specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>دار إنتاج سينمائي رائدة في مملكة البحرين، متخصصة في صناعة الأفلام الإعلانية الوثائقية والتصوير الجوي السينمائي.</p><p>من خلال خدمة <strong>إنتاج البودكاست المرئي التنفيذي</strong>، يعمل فريقنا في Manama على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-03.png', 'What Happens in Your First 14 Days With ishoot | ishoot', 'خارطة الأيام الـ14 الأولى مع فريق آي شوت | آي شوت', 'Executive guide by ishoot covering Executive Video Podcast Production benchmarks in Bahrain.', 'دليل تنفيذي من آي شوت حول معايير إنتاج البودكاست المرئي التنفيذي في البحرين.', 'Client Care', '{"media","client care","Manama","2026"}'::text[], 'Bader Ali', 'published', now() - interval '72 days', false, now() - interval '72 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-12', 'What post-delivery guarantee covers your work?', 'ما الضمان المقدم بعد التسليم النهائي؟', 'All engagements include a structured handover checklist and 30-to-90 day defect/warranty support window.', 'تشمل جميع المشاريع قائمة استلام موثقة وفترة ضمان ودعم تمتد بين 30 و90 يوماً بعد التسليم.', 'warranty', true, 12, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
